contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(_c.owner()); }

    // Test calls withdraw, withdrawAll, sendMoney and also triggers fallback by sending Ether.
    // Inputs:
    // - sendAmt: amount of wei to send to c to trigger fallback
    // - callAmt: amount passed to withdraw/sendMoney
    // - target: address passed to sendMoney (here we use address(this) or any)
    function run(uint sendAmt, uint callAmt, address target) public payable {
        require(address(this).balance >= sendAmt);

        // Read before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Trigger fallback by sending Ether to c (will increment depositsCount)
        if (sendAmt > 0) {
            // ensure this contract has enough balance to send
            (bool sent,) = address(c).call{value: sendAmt}("");
            // sent may be true or false depending on C, but fallback increments only on payable fallback
            // We don't revert here; we will observe effects below.
            sent; // silence unused warning
        }

        // Attempt withdrawAll from this contract (not owner) and record whether it reverts
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Attempt withdraw(callAmt)
        bool withdrawReverted;
        try c.withdraw(callAmt) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Attempt sendMoney to `target` with callAmt
        bool sendMoneyReverted;
        try c.sendMoney(target, callAmt) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read after state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // 1) If this contract is not the owner, withdraw/withdrawAll/sendMoney must revert (i.e., all three revert flags true).
        // 2) depositsCount after is either equal to before or increased by 1 when a payable call succeeded in sending Ether.
        // We express owner-check by comparing deployer (owner at construction) to address(this).

        bool amOwner = (deployer == address(this));

        assert(
            (
                // If this contract is not owner then all privileged calls revert
                (!amOwner && withdrawAllReverted && withdrawReverted && sendMoneyReverted)
                // If this contract is owner then privileged calls may or may not revert; we don't constrain them here
            )
            &&
            (
                // depositsCount either unchanged or increased by at least 1, and c's balance reflects that non-negative change
                (afterDeposits == beforeDeposits || afterDeposits == beforeDeposits + 1)
                && (afterBalance >= beforeBalance)
            )
        );
    }

    // Allow receiving Ether if C sends to this contract during tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run a single transaction test. Inputs:
    // - sendAmt: amount of wei this test will try to send to c via c.fallback (using address(c).call)
    // - callAmt: amount to pass into withdraw/sendMoney
    // - target: address passed to sendMoney
    function run(uint sendAmt, uint callAmt, address target) public payable {
        require(address(this).balance >= sendAmt);

        // Read before state (public getters)
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Try to send Ether to c to trigger fallback (this is NOT a call on c via its typed interface, but is allowed)
        bool sendSucceeded;
        (sendSucceeded, ) = address(c).call{value: sendAmt}("");

        // Attempt privileged calls and catch whether they revert. Each state-changing call on c is a top-level statement.
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(callAmt) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, callAmt) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read after state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Who is owner? Only observable via c.owner() public getter.
        address owner = c.owner();
        bool amOwner = (owner == address(this));

        // Assert the general rule:
        // - If this contract is not the owner, all three privileged calls must revert.
        // - If the external low-level send to c succeeded (sendSucceeded==true and sendAmt>0), then depositsCount increases by exactly 1 and c's balance increases by at least sendAmt.
        // Note: when sendAmt==0, the fallback may or may not increment depositsCount per contract logic; we only assert the increment case when a nonzero send succeeded.
        assert(
            (
                (!amOwner && withdrawAllReverted && withdrawReverted && sendMoneyReverted) || amOwner
            )
            &&
            (
                // If a nonzero send succeeded, depositsCount must increase exactly by 1 and balance not decrease.
                (!sendSucceeded || sendAmt == 0) || (afterDeposits == beforeDeposits + 1 && afterBalance >= beforeBalance + sendAmt)
            )
        );
    }

    // Allow receiving Ether if C sends to this contract during tests
    receive() external payable {}
}

