contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept Ether forwarded from C during withdraw/sendMoney
    receive() external payable {}

    // params: callerIsOwner indicates whether this contract will act as owner (must always be true here because c.owner == deployer which is this contract),
    // amount: amount of wei to try to withdraw/send
    // targetIsThis: if true, call sendMoney to send to this test contract; otherwise call withdraw
    function run(bool targetIsThis, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test to fund calls");

        // Fund C by sending Ether to its fallback which increments depositsCount
        // Do this once with `amount` to ensure c has some balance to operate on.
        c.f{value: amount}();

        // Read before balances
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // Decide which owner-only action to perform. This contract is the owner of c (deployer),
        // so calls should succeed if amount <= beforeC.
        bool reverted;
        // perform either withdrawAll, withdraw(amount) or sendMoney(this, amount)
        if (beforeC < amount) {
            // If requested amount is more than available balance, withdraw(amount) or sendMoney should revert,
            // but withdrawAll should succeed and transfer the whole balance. We will call both kinds to observe behavior.
            // First try withdraw(amount)
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // Now try sendMoney; sending more than balance should revert similarly
            bool reverted2;
            try c.sendMoney(address(this), amount) {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            // At least one of withdraw or sendMoney must have reverted when amount > beforeC (owner cannot extract more than balance)
            assert(reverted || reverted2);

        } else {
            // amount <= beforeC: both withdraw(amount) and sendMoney should succeed when called by owner.
            // We'll call withdraw(amount) and then call sendMoney to send the same amount back into c and then withdrawAll.
            // First, withdraw amount
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After a successful withdraw, c's balance should decrease by amount and this contract's balance increase by amount
            uint midC = address(c).balance;
            uint midThis = address(this).balance;
            if (!reverted) {
                assert(midC + amount == beforeC);
                assert(midThis == beforeThis + amount);
            }

            // Now send the withdrawn amount back into c via its fallback by calling c.f with value
            require(address(this).balance >= amount, "need balance to fund fallback");
            c.f{value: amount}();

            // Now call withdrawAll to drain entire contract balance back to owner (this)
            uint afterFundC = address(c).balance;
            try c.withdrawAll() {
                // withdrawAll should succeed and transfer afterFundC to this contract
                uint finalC = address(c).balance;
                uint finalThis = address(this).balance;
                assert(finalC == 0);
                assert(finalThis == midThis); // midThis already included the first withdraw; after funding and withdrawAll it should be unchanged relative to midThis
            } catch {
                // withdrawAll failed unexpectedly
                assert(false);
            }
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept Ether forwarded from C during withdraw/sendMoney
    receive() external payable {}

    // We use `fund` amount to send into C via its fallback (which increments depositsCount).
    // Then attempt an owner withdraw of `amountToWithdraw` and assert the general rule:
    // if withdraw reverts then amountToWithdraw > balance_before; otherwise balance decreased by exactly amountToWithdraw and this contract's balance increased by that amount.
    function run(uint fund, uint amountToWithdraw) public payable {
        // ensure this test contract has enough ether to fund C via fallback
        require(address(this).balance >= fund, "insufficient balance to fund C");

        // Fund C by invoking its fallback: send Ether directly to address(c)
        // Use low-level call so we trigger fallback (C has no payable receive).
        (bool okFund, ) = address(c).call{value: fund}("");
        require(okFund, "funding call failed");

        // Read before-values
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt owner withdraw(amountToWithdraw)
        bool reverted;
        try c.withdraw(amountToWithdraw) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted below:
        // - depositsCount should not decrease due to withdraw
        // - If withdraw reverted then amountToWithdraw > beforeC (cannot withdraw more than available)
        // - If withdraw did not revert then C's balance decreased by exactly amountToWithdraw and this contract's balance increased by exactly amountToWithdraw
        assert(
            // depositsCount monotone non-decreasing
            afterDeposits >= beforeDeposits
            // and either revert implies attempted amount greater than available
            && (reverted ? (amountToWithdraw > beforeC) : true)
            // or non-revert implies exact transfer accounting
            && (!reverted ? (beforeC == afterC + amountToWithdraw && afterThis == beforeThis + amountToWithdraw) : true)
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    // fund and amountToWithdraw are inputs; fund is sent to C via its fallback by calling c.fallback via a plain call to address(c).
    function run(uint fund, uint amountToWithdraw) public payable {
        // Ensure this test contract has enough ether to fund C
        require(address(this).balance >= fund, "insufficient balance to fund C");

        // Call C's fallback by sending Ether directly to address(c) (this is a state-changing external call but not via c.f(...)).
        // This must be a top-level statement. Use low-level call on address(c) (allowed) — it is not a call on c, so it's fine.
        (bool okFund, ) = address(c).call{value: fund}("");
        require(okFund, "funding call failed");

        // Read public observable values before withdraw
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt owner withdraw(amountToWithdraw) as a top-level state-changing call on c and capture revert
        bool reverted;
        try c.withdraw(amountToWithdraw) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // Assert the general invariant:
        // - depositsCount does not decrease due to withdraw
        // - If withdraw reverted then amountToWithdraw > beforeC
        // - If withdraw succeeded then C's balance decreased by exactly amountToWithdraw and this contract's balance increased by exactly amountToWithdraw
        assert(
            afterDeposits >= beforeDeposits
            && (reverted ? (amountToWithdraw > beforeC) : (beforeC == afterC + amountToWithdraw && afterThis == beforeThis + amountToWithdraw))
        );
    }
}

