contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test takes parameters to try calls as the InvMutTest contract (which is NOT the owner of c).
    // It asserts that when this (non-owner) contract attempts to withdraw/withdrawAll/sendMoney, the calls revert
    // and the observable state (address(c).balance and c.depositsCount()) remain unchanged.
    function run(address payable target, uint value, uint sendToTargetValue) public payable {
        require(address(this).balance >= value && address(this).balance >= sendToTargetValue, "insufficient balance");

        // Deposit some Ether into c by triggering fallback via a direct call with value from this contract.
        // Call fallback by sending value to c.
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // make a deposit to change state so that we can observe that failed withdraws don't alter it
        c.f{value: value}();
        uint afterDepositBalance = address(c).balance;
        uint afterDepositDeposits = c.depositsCount();

        // ensure deposit had observable effect (so the test is meaningful)
        // note: this is a require only about local observed values, not about c internals
        require(afterDepositBalance >= beforeBalance + value && afterDepositDeposits == beforeDeposits + 1, "deposit failed setup");

        // Attempt withdraw (should revert because InvMutTest is not owner). Capture revert flags.
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, sendToTargetValue) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read post-call observable state
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // Assert: if any of the three calls reverted (as expected for non-owner), then c's balance and depositsCount didn't decrease.
        // Also assert that NONE of the calls succeeded (since this contract is not owner), i.e., all reverted.
        assert(withdrewReverted && withdrawAllReverted && sendMoneyReverted && finalBalance == afterDepositBalance && finalDeposits == afterDepositDeposits);
    }

    // allow receiving Ether so the test contract can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run as the InvMutTest contract (which is NOT the owner of c).
    // Params: target address for sendMoney, depositAmount to send into c, sendToTargetValue for sendMoney call.
    function run(address payable target, uint depositAmount, uint sendToTargetValue) public payable {
        // Ensure this test contract has enough Ether to make the deposit and potentially send during sendMoney attempt
        require(address(this).balance >= depositAmount && address(this).balance >= sendToTargetValue);

        // Observe before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Make a deposit by sending Ether to c to trigger fallback()
        // Must be its own top-level call. Use low-level call to send value to c so fallback triggers.
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // Observe after deposit
        uint afterDepositBalance = address(c).balance;
        uint afterDepositDeposits = c.depositsCount();

        // Sanity: deposit should increase balance by depositAmount and depositsCount by 1
        require(afterDepositBalance >= beforeBalance + depositAmount && afterDepositDeposits == beforeDeposits + 1);

        // Attempt withdraw — should revert because this contract is not owner
        bool withdrewReverted;
        try c.withdraw(depositAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Attempt withdrawAll — should revert for non-owner
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Attempt sendMoney to target — should revert for non-owner (and must not change c balance if it reverts)
        bool sendMoneyReverted;
        try c.sendMoney(target, sendToTargetValue) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read final observable state
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule: for a non-owner caller, all three privileged calls revert, and c's balance and depositsCount remain as after the deposit.
