contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters specifying which action to attempt and values.
    // callerIsOwner selects whether this contract should act as owner (true) or simulate non-owner (false).
    // Since InvMutTest deployed C, this contract is the owner. To test non-owner behavior we forward a call
    // from an externally controlled address by using a try/catch on an external call target.

    // We will attempt three actions depending on actionId: 0=withdrawAll(), 1=withdraw(uint), 2=sendMoney(address,uint)
    // amount is used for withdraw/sendMoney value; target is used for sendMoney target.
    function run(uint8 actionId, uint amount, address payable target, bool asOwner) public payable {
        require(actionId <= 2);
        // Ensure we have enough funds to send to C if needed.
        // When depositing to C we must call its fallback to change balance/depositsCount for observable state.
        // First record before-values.
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // If we want to test withdraw/withdrawAll/sendMoney as non-owner, we need to originate the call from a non-owner address.
        // We simulate a non-owner by invoking a helper contract deployed on-the-fly is not allowed; instead, use the fact
        // that c.owner == address(this) (InvMutTest) because InvMutTest deployed C. So to simulate non-owner, we will
        // perform the call via a low-level call from this contract but using address(c).call with data encoding a function
        // and setting msg.sender will still be this contract — we cannot change msg.sender. Therefore we instead assert
        // a weaker property: if the call is initiated by the actual owner (asOwner==true), it must not revert; if initiated
        // by a non-owner (asOwner==false) we assert that a reversion would occur if a non-owner were to call. Since we cannot
        // change msg.sender here, we detect that and only attempt the owner call when asOwner==true; when asOwner==false
        // we do not actually perform the call but assert that a non-owner would be prevented by owner guard. To make this
        // observable, we require that c.owner() != address(0) and then assert the logical implication.

        // Ensure contract has some ETH to withdraw/send if testing owner path.
        if (msg.value > 0) {
            // deposit into C via fallback to increase balance and depositsCount
            require(address(this).balance >= msg.value);
            // Call fallback on c to deposit msg.value
            (bool ok, ) = address(c).call{value: msg.value}("");
            // allow fallback to possibly revert; if it reverts the test run will revert here
            require(ok);
        }

        // Read owner
        address owner = c.owner();

        bool didRevert = false;
        if (asOwner) {
            // asOwner must be true only when this contract is the owner
            require(owner == address(this));

            // perform the chosen owner action and catch revert
            if (actionId == 0) {
                try c.withdrawAll() {
                    didRevert = false;
                } catch {
                    didRevert = true;
                }
            } else if (actionId == 1) {
                try c.withdraw(amount) {
                    didRevert = false;
                } catch {
                    didRevert = true;
                }
            } else {
                // sendMoney
                try c.sendMoney(target, amount) {
                    didRevert = false;
                } catch {
                    didRevert = true;
                }
            }

            // After owner attempt, balance of c should have decreased by at most amount (cannot create ether)
            uint afterBalance = address(c).balance;
            uint afterDeposits = c.depositsCount();

            // If the owner call reverted then state should be unchanged; otherwise balance may have reduced by up to amount
            if (didRevert) {
                assert(afterBalance == beforeBalance);
                assert(afterDeposits == beforeDeposits);
            } else {
                // If successful and it was withdrawAll, then afterBalance must be either 0 or unchanged if amount was 0
                if (actionId == 0) {
                    // withdrawAll should transfer entire balance away, so afterBalance == 0
                    assert(afterBalance == 0);
                } else {
                    // withdraw(amount) or sendMoney may reduce by at most amount
                    assert(afterBalance + amount >= beforeBalance);
                    // depositsCount should be unchanged by withdraw/sendMoney
                    assert(afterDeposits == beforeDeposits);
                }
            }

        } else {
            // asOwner == false: we cannot actually make calls from a different msg.sender here, so we instead assert the intended rule:
            // For any caller that is not owner, calls to withdraw, withdrawAll, and sendMoney must revert and not change balance or depositsCount.
            // We can check that by asserting c.owner() != address(0) and that owner != address(this) implies owner-only protection exists.
            // Since we cannot observe reverts for other senders, express the general rule as: if owner != this contract then these functions
            // must be guarded by onlyOwner. We assert that if owner != address(this) then attempting the call as owner would not be allowed
            // — but this is observationally equivalent to owner != address(this). So here we assert that when owner != address(this), it is
            // not possible for this contract to call them successfully (i.e., they would revert). We check that by trying and expecting revert.

            // Ensure owner indeed differs
            require(owner != address(this));

            bool r0;
            try c.withdrawAll() {
                r0 = false;
            } catch {
                r0 = true;
            }
            bool r1;
            try c.withdraw(amount) {
                r1 = false;
            } catch {
                r1 = true;
            }
            bool r2;
            try c.sendMoney(target, amount) {
                r2 = false;
            } catch {
                r2 = true;
            }

            uint afterBalance = address(c).balance;
            uint afterDeposits = c.depositsCount();

            // General rule: all three must revert for non-owners, and state remains unchanged
            assert(r0 && r1 && r2 && afterBalance == beforeBalance && afterDeposits == beforeDeposits);
        }
    }

    receive() external payable {}
}

