    constructor(C _c) { c = _c; deployer = address(this); }
    // We declare a payable public function that will try calls as either owner or non-owner.
    // Parameters:
    // - asOwner: if true, we will call functions by the owner (this contract is owner), otherwise we simulate a non-owner call by using a target contract call.
    // - callKind: 0 = withdrawAll(), 1 = withdraw(amount), 2 = sendMoney(target, amount)
    // - amount: amount used for withdraw or sendMoney
    // - target: target address for sendMoney (must be a contract or address)
    function run(bool asOwner, uint callKind, uint amount, address payable target) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        // read observables before
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool reverted;

        if (asOwner) {
            // calls made directly from this contract (which is the owner)
            if (callKind == 0) {
                // withdrawAll
                try c.withdrawAll{value: 0}() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else if (callKind == 1) {
                try c.withdraw{value: 0}(amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // sendMoney
                try c.sendMoney{value: 0}(target, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // simulate a non-owner by calling through a thin proxy contract deployed on the fly.
            // Deploy minimal proxy that forwards calls to c. It will have a different msg.sender when calling c.
            NonOwnerProxy p = new NonOwnerProxy(c);
            if (callKind == 0) {
                try p.callWithdrawAll() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else if (callKind == 1) {
                try p.callWithdraw(amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                try p.callSendMoney(target, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        }

        // read observables after
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if non-owner call was attempted it must revert and neither depositsCount nor balance change;
        // if owner call was attempted it may or may not revert, but no invariant is required here about depositsCount/balance except that they must not decrease below zero (balances are unsigned) — we assert only the owner vs non-owner property.
        if (!asOwner) {
