        // and that final balance is >= midBalance minus the sum of amounts for which the corresponding call did NOT revert.

        uint expectedMaxDecrease = 0;
        if (!withdrewSpecificReverted) { expectedMaxDecrease += sendAmount; }
        if (!withdrewAllReverted) { expectedMaxDecrease += midBalance >= 0 ? midBalance : 0; }
        if (!sendMoneyReverted) { expectedMaxDecrease += sendAmount; }

