    // allow receiving Ether when C transfers out to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run will attempt an owner-only action from a caller that is NOT the owner (this contract).
    // Parameters: target address for sendMoney, value to attempt to withdraw/send, and a flag to choose which function.
    function run(address payable target, uint value, uint choice) public payable {
        require(true);
        // ensure this contract has enough ETH to send if we choose to call sendMoney via value param
        // (we won't send value to c here; we only call owner-only functions which transfer FROM c to this contract/target)

        // Read observable before-state
        uint beforeDepositsCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted = false;
        // choice: 0 = withdrawAll(), 1 = withdraw(value), 2 = sendMoney(target, value)
        if (choice == 0) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (choice == 1) {
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.sendMoney(target, value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read observable after-state
        uint afterDepositsCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: since InvMutTest is NOT the owner (owner is deployer of C), any owner-only call must revert
        // and must not change depositsCount or contract balance.
        assert(reverted && afterDepositsCount == beforeDepositsCount && afterBalance == beforeBalance);
    }

    // receive so this test contract can accept funds if needed during environment setup
    receive() external payable {}
}

