contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test sendMoney behavior. This contract deployed C and is its owner.
    // Parameters: target address to receive funds, and amount to send from C to target.
    // The test funds C first via its payable fallback by sending fundAmount from this contract.
    function run(address payable target, uint fundAmount, uint sendAmount) public payable {
        // Ensure this test contract has funds to fund C
        require(address(this).balance >= fundAmount, "insufficient balance to fund C");

        // Fund C by calling its fallback with value fundAmount. This is a top-level state-changing call.
        (bool okFunding, ) = address(c).call{value: fundAmount}("");
        require(okFunding, "funding C failed");

        // Record balances before sendMoney
        uint beforeC = address(c).balance;
        uint beforeTarget = address(target).balance;

        // Perform the sendMoney call as owner: top-level state-changing call
        bool reverted;
        try c.sendMoney(target, sendAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record balances after
        uint afterC = address(c).balance;
        uint afterTarget = address(target).balance;

        // General rule:
        // If sendMoney did not revert then C's balance decreased by exactly sendAmount (unless sendAmount > beforeC then call should have reverted),
        // and target's balance increased by exactly sendAmount. If it reverted then balances remain unchanged.
        // Expressed without underflows: two cases depending on reverted flag and whether sendAmount <= beforeC.
        assert(
            (
                reverted && afterC == beforeC && afterTarget == beforeTarget
            ) || (
                !reverted && sendAmount <= beforeC && afterC + sendAmount == beforeC && afterTarget == beforeTarget + sendAmount
            )
        );
    }

    // Allow receiving ETH when funding C and when C sends funds here
    receive() external payable {}
}

