contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run attempts owner-restricted operations from this contract (which is NOT the original owner of C)
    // params: amount to withdraw/send, and target address for sendMoney (must not be zero to avoid trivial revert)
    function run(uint amount, address payable target) public payable {
        require(target != address(0));
        // Pre-read observable state
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Attempt withdraw(uint)
        bool revertedWithdrawUint;
        try c.withdraw{value:0}(amount) {
            revertedWithdrawUint = false;
        } catch {
            revertedWithdrawUint = true;
        }
        // Attempt withdrawAll()
        bool revertedWithdrawAll;
        try c.withdrawAll{value:0}() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }
        // Attempt sendMoney
        bool revertedSendMoney;
        // sendMoney is payable on target side but call from c doesn't need value from this test; we pass amount param
        try c.sendMoney{value:0}(target, amount) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        // After values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if any of these owner-only calls did not revert when invoked by this contract,
        // then C must have allowed it (meaning this contract is owner). Otherwise (expected), when they revert,
        // they must not have changed depositsCount or balance. We assert that for every call that reverted, no state change occurred.
        // This avoids asserting the contract's ownership (which may be true for some runs) but enforces that reverts protect storage.
        assert(
            (revertedWithdrawUint ? (afterCount == beforeCount && afterBal == beforeBal) : true)
            && (revertedWithdrawAll ? (afterCount == beforeCount && afterBal == beforeBal) : true)
            && (revertedSendMoney ? (afterCount == beforeCount && afterBal == beforeBal) : true)
        );
    }

    receive() external payable {}
}

